import { useState, useEffect, useRef } from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMapEvents } from 'react-leaflet';
import { useTranslation } from 'react-i18next';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';

// Fix for default markers in react-leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
});

// Draggable User Location Marker Component
const DraggableMarker = ({ position, setPosition }) => {
  const markerRef = useRef(null);
  
  const eventHandlers = {
    dragend() {
      const marker = markerRef.current;
      if (marker != null) {
        const newPos = marker.getLatLng();
        setPosition({ lat: newPos.lat, lng: newPos.lng });
      }
    },
  };

  return (
    <Marker
      draggable={true}
      eventHandlers={eventHandlers}
      position={[position.lat, position.lng]}
      ref={markerRef}
      icon={new L.Icon({
        iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
        iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
        shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
        iconSize: [25, 41],
        iconAnchor: [12, 41],
        popupAnchor: [1, -34],
        shadowSize: [41, 41],
        className: 'user-location-marker'
      })}
    >
      <Popup>
        <div>
          <strong>Your Location</strong><br />
          <small>Drag this marker to change your location</small><br />
          <small>Lat: {position.lat.toFixed(4)}, Lng: {position.lng.toFixed(4)}</small>
        </div>
      </Popup>
    </Marker>
  );
};

// Map Click Handler Component
const MapClickHandler = ({ onMapClick }) => {
  useMapEvents({
    click: onMapClick,
  });
  return null;
};

const HealthcareMap = () => {
  const { t } = useTranslation();
  const [clinics, setClinics] = useState([]);
  const [userLocation, setUserLocation] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selectedType, setSelectedType] = useState('');
  const [searchRadius, setSearchRadius] = useState(10000); // 10km default

  // Default location (Pune, Maharashtra)
  const defaultLocation = { lat: 18.5204, lng: 73.8567 };

  useEffect(() => {
    getUserLocation();
  }, []);

  useEffect(() => {
    if (userLocation) {
      fetchNearbyClinics();
    }
  }, [userLocation, selectedType, searchRadius]);

  const getUserLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setUserLocation({
            lat: position.coords.latitude,
            lng: position.coords.longitude
          });
        },
        (error) => {
          console.error('Error getting location:', error);
          setUserLocation(defaultLocation);
          setError('Using default location. Please enable location access for better results.');
        }
      );
    } else {
      setUserLocation(defaultLocation);
      setError('Geolocation not supported. Using default location.');
    }
  };

  const fetchNearbyClinics = async () => {
    if (!userLocation) return;

    setLoading(true);
    setError('');
    
    try {
      // Check if Google Maps is loaded
      if (!window.google || !window.google.maps || !window.google.maps.places) {
        // Fallback to mock data for demo
        const mockClinics = generateMockClinics(userLocation, selectedType, searchRadius);
        setClinics(mockClinics);
        setLoading(false);
        return;
      }

      // Use Google Places API to find nearby healthcare facilities
      const service = new window.google.maps.places.PlacesService(document.createElement('div'));
      
      const request = {
        location: new window.google.maps.LatLng(userLocation.lat, userLocation.lng),
        radius: searchRadius,
        type: getGooglePlaceType(selectedType),
        keyword: 'healthcare hospital clinic medical doctor pharmacy'
      };

      service.nearbySearch(request, (results, status) => {
        if (status === window.google.maps.places.PlacesServiceStatus.OK && results) {
          const formattedClinics = results.map(place => ({
            _id: place.place_id,
            name: place.name,
            type: mapGoogleTypeToLocal(place.types),
            coordinates: {
              latitude: place.geometry.location.lat(),
              longitude: place.geometry.location.lng()
            },
            contact: {
              phone: place.formatted_phone_number || 'Contact for details'
            },
            address: {
              street: place.vicinity || place.formatted_address,
              village: extractLocationComponent(place, 'locality') || 'Local area',
              district: extractLocationComponent(place, 'administrative_area_level_2') || 'District'
            },
            rating: place.rating || 0,
            isOpen: place.opening_hours?.open_now,
            distance: calculateDistance(
              userLocation.lat,
              userLocation.lng,
              place.geometry.location.lat(),
              place.geometry.location.lng()
            )
          }));

          setClinics(formattedClinics);
          
          if (formattedClinics.length === 0) {
            setError('No healthcare facilities found in the selected area. Try increasing the search radius.');
          }
        } else {
          // Fallback to mock data
          const mockClinics = generateMockClinics(userLocation, selectedType, searchRadius);
          setClinics(mockClinics);
          if (mockClinics.length === 0) {
            setError('No healthcare facilities found in the selected area. Try increasing the search radius.');
          }
        }
        setLoading(false);
      });

    } catch (error) {
      console.error('Failed to fetch clinics:', error);
      // Fallback to mock data
      const mockClinics = generateMockClinics(userLocation, selectedType, searchRadius);
      setClinics(mockClinics);
      setError('Using sample data. For live results, ensure Google Maps API is configured.');
      setLoading(false);
    }
  };

  const generateMockClinics = (location, type, radius) => {
    const mockData = [
      {
        _id: 'mock-1',
        name: 'City General Hospital',
        type: 'hospital',
        coordinates: { latitude: location.lat + 0.01, longitude: location.lng + 0.01 },
        contact: { phone: '+91-9876543210' },
        address: { street: 'Main Road', village: 'City Center', district: 'Urban District' },
        rating: 4.2,
        isOpen: true,
        distance: 1.2
      },
      {
        _id: 'mock-2',
        name: 'Family Care Clinic',
        type: 'clinic',
        coordinates: { latitude: location.lat - 0.005, longitude: location.lng + 0.008 },
        contact: { phone: '+91-9876543211' },
        address: { street: 'Health Street', village: 'Medical Colony', district: 'Health District' },
        rating: 4.0,
        isOpen: true,
        distance: 0.8
      },
      {
        _id: 'mock-3',
        name: 'MedPlus Pharmacy',
        type: 'pharmacy',
        coordinates: { latitude: location.lat + 0.003, longitude: location.lng - 0.006 },
        contact: { phone: '+91-9876543212' },
        address: { street: 'Pharmacy Lane', village: 'Medicine Market', district: 'Commercial District' },
        rating: 3.8,
        isOpen: true,
        distance: 0.5
      },
      {
        _id: 'mock-4',
        name: 'Rural Health Center',
        type: 'health_center',
        coordinates: { latitude: location.lat - 0.008, longitude: location.lng - 0.004 },
        contact: { phone: '+91-9876543213' },
        address: { street: 'Village Road', village: 'Rural Area', district: 'Rural District' },
        rating: 3.5,
        isOpen: true,
        distance: 1.0
      }
    ];

    // Filter by type if specified
    let filtered = type ? mockData.filter(clinic => clinic.type === type) : mockData;
    
    // Filter by radius (convert km to degrees roughly)
    const maxDistance = radius / 111000; // Rough conversion
    filtered = filtered.filter(clinic => {
      const distance = Math.sqrt(
        Math.pow(clinic.coordinates.latitude - location.lat, 2) +
        Math.pow(clinic.coordinates.longitude - location.lng, 2)
      );
      return distance <= maxDistance;
    });

    return filtered;
  };

  const getGooglePlaceType = (localType) => {
    const typeMap = {
      'hospital': 'hospital',
      'clinic': 'doctor',
      'health_center': 'health',
      'pharmacy': 'pharmacy',
      'diagnostic_center': 'health'
    };
    return typeMap[localType] || 'health';
  };

  const mapGoogleTypeToLocal = (googleTypes) => {
    if (!googleTypes) return 'clinic';
    if (googleTypes.includes('hospital')) return 'hospital';
    if (googleTypes.includes('pharmacy')) return 'pharmacy';
    if (googleTypes.includes('doctor') || googleTypes.includes('health')) return 'clinic';
    return 'health_center';
  };

  const extractLocationComponent = (place, componentType) => {
    if (!place.address_components) return '';
    const component = place.address_components.find(comp => 
      comp.types.includes(componentType)
    );
    return component ? component.long_name : '';
  };

  // Calculate distance between two coordinates using Haversine formula
  const calculateDistance = (lat1, lon1, lat2, lon2) => {
    const R = 6371; // Radius of the Earth in kilometers
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = 
      Math.sin(dLat/2) * Math.sin(dLat/2) +
      Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * 
      Math.sin(dLon/2) * Math.sin(dLon/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    const distance = R * c; // Distance in kilometers
    return distance;
  };

  const handleMapClick = (e) => {
    const { lat, lng } = e.latlng;
    setUserLocation({ lat, lng });
  };

  const getClinicIcon = (type) => {
    const iconColors = {
      hospital: '#dc3545',
      clinic: '#007bff',
      health_center: '#28a745',
      pharmacy: '#ffc107',
      diagnostic_center: '#6f42c1'
    };

    return new L.Icon({
      iconUrl: `data:image/svg+xml;base64,${btoa(`
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="${iconColors[type] || '#007bff'}" width="24" height="24">
          <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/>
        </svg>
      `)}`,
      iconSize: [30, 30],
      iconAnchor: [15, 30],
      popupAnchor: [0, -30]
    });
  };

  const formatDistance = (distance) => {
    if (distance < 1) {
      return `${Math.round(distance * 1000)}m`;
    }
    return `${distance.toFixed(1)}km`;
  };

  const getDirections = (clinic) => {
    const url = `https://www.google.com/maps/dir/?api=1&destination=${clinic.coordinates.latitude},${clinic.coordinates.longitude}`;
    window.open(url, '_blank');
  };

  if (!userLocation) {
    return (
      <div className="loading">
        <div className="spinner"></div>
        <p>Getting your location...</p>
      </div>
    );
  }

  return (
    <div className="container map-container fade-in">
      <div className="card-header text-center">
        <h1 className="card-title">{t('map.nearbyHealthcare')}</h1>
        <p>Find healthcare facilities near you</p>
      </div>

      {error && <div className="alert alert-warning">{error}</div>}

      {/* Filters */}
      <div className="card mb-20">
        <div className="form-row">
          <div className="form-group">
            <label className="form-label">Facility Type</label>
            <select
              className="form-select"
              value={selectedType}
              onChange={(e) => setSelectedType(e.target.value)}
            >
              <option value="">All Types</option>
              <option value="hospital">Hospital</option>
              <option value="clinic">Clinic</option>
              <option value="health_center">Health Center</option>
              <option value="pharmacy">Pharmacy</option>
              <option value="diagnostic_center">Diagnostic Center</option>
            </select>
          </div>

          <div className="form-group">
            <label className="form-label">Search Radius</label>
            <select
              className="form-select"
              value={searchRadius}
              onChange={(e) => setSearchRadius(parseInt(e.target.value))}
            >
              <option value="5000">5 km</option>
              <option value="10000">10 km</option>
              <option value="25000">25 km</option>
              <option value="50000">50 km</option>
            </select>
          </div>

          <div className="form-group">
            <label className="form-label">&nbsp;</label>
            <button className="btn" onClick={fetchNearbyClinics}>
              🔍 Search
            </button>
          </div>
        </div>
      </div>

      <div className="grid grid-2">
        {/* Map */}
        <div className="map-wrapper">
          <div className="map-instructions">
            <p>📍 <strong>Tip:</strong> Drag the blue marker to change your location, or click anywhere on the map to set a new location.</p>
          </div>
          <MapContainer
            center={[userLocation.lat, userLocation.lng]}
            zoom={12}
            style={{ height: '500px', width: '100%' }}
          >
            <TileLayer
              url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
              attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
            />
            
            {/* Map click handler */}
            <MapClickHandler onMapClick={handleMapClick} />
            
            {/* Draggable user location marker */}
            <DraggableMarker 
              position={userLocation} 
              setPosition={setUserLocation}
            />

            {/* Clinic markers */}
            {clinics.map((clinic) => (
              <Marker
                key={clinic._id}
                position={[clinic.coordinates.latitude, clinic.coordinates.longitude]}
                icon={getClinicIcon(clinic.type)}
              >
                <Popup>
                  <div style={{ minWidth: '200px' }}>
                    <h4>{clinic.name}</h4>
                    <p><strong>Type:</strong> {clinic.type.replace('_', ' ')}</p>
                    <p><strong>Distance:</strong> {formatDistance(clinic.distance)}</p>
                    {clinic.contact?.phone && (
                      <p><strong>Phone:</strong> {clinic.contact.phone}</p>
                    )}
                    {clinic.address && (
                      <p><strong>Address:</strong> {clinic.address.village}, {clinic.address.district}</p>
                    )}
                    <button
                      className="btn btn-secondary"
                      onClick={() => getDirections(clinic)}
                      style={{ width: '100%', marginTop: '10px' }}
                    >
                      Get Directions
                    </button>
                  </div>
                </Popup>
              </Marker>
            ))}
          </MapContainer>
        </div>

        {/* Clinic List */}
        <div className="card">
          <div className="card-header">
            <h3 className="card-title">
              Nearby Facilities ({clinics.length})
            </h3>
          </div>

          {loading ? (
            <div className="loading">
              <div className="spinner"></div>
            </div>
          ) : clinics.length === 0 ? (
            <div className="text-center p-20">
              <p>No healthcare facilities found in the selected area.</p>
            </div>
          ) : (
            <div style={{ maxHeight: '400px', overflowY: 'auto' }}>
              {clinics.map((clinic) => (
                <div key={clinic._id} className="queue-item">
                  <div className="queue-patient-info">
                    <div className="queue-patient-name">
                      {clinic.name}
                    </div>
                    <div className="queue-patient-details">
                      <strong>Type:</strong> {clinic.type.replace('_', ' ')} |
                      <strong> Distance:</strong> {formatDistance(clinic.distance)}
                    </div>
                    {clinic.address && (
                      <div className="queue-patient-details">
                        {clinic.address.village}, {clinic.address.district}
                      </div>
                    )}
                    {clinic.contact?.phone && (
                      <div className="queue-patient-details">
                        📞 {clinic.contact.phone}
                      </div>
                    )}
                    {clinic.services && clinic.services.length > 0 && (
                      <div className="queue-patient-details">
                        <strong>Services:</strong> {clinic.services.slice(0, 3).map(s => s.name).join(', ')}
                        {clinic.services.length > 3 && '...'}
                      </div>
                    )}
                  </div>

                  <div className="queue-actions">
                    <button
                      className="btn btn-secondary"
                      onClick={() => getDirections(clinic)}
                    >
                      🗺️ Directions
                    </button>
                    {clinic.contact?.phone && (
                      <button
                        className="btn btn-success"
                        onClick={() => window.open(`tel:${clinic.contact.phone}`)}
                      >
                        📞 Call
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Legend */}
      <div className="card">
        <h4>Map Legend</h4>
        <div className="grid grid-3">
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{ width: '20px', height: '20px', backgroundColor: '#dc3545', borderRadius: '50%' }}></div>
            <span>Hospital</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{ width: '20px', height: '20px', backgroundColor: '#007bff', borderRadius: '50%' }}></div>
            <span>Clinic</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{ width: '20px', height: '20px', backgroundColor: '#28a745', borderRadius: '50%' }}></div>
            <span>Health Center</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{ width: '20px', height: '20px', backgroundColor: '#ffc107', borderRadius: '50%' }}></div>
            <span>Pharmacy</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{ width: '20px', height: '20px', backgroundColor: '#6f42c1', borderRadius: '50%' }}></div>
            <span>Diagnostic Center</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default HealthcareMap;
